CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS venues (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), yelp_id TEXT UNIQUE NOT NULL, name TEXT NOT NULL, address TEXT, city TEXT, state TEXT, latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, yelp_rating NUMERIC(2,1), review_count INTEGER DEFAULT 0, price_level TEXT, cuisine TEXT[], is_open BOOLEAN DEFAULT TRUE, photo_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPT@ DESFAULT NOW());
CREATE TABLE IF NOT EXISTS trend_signals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), venue_id UUID REFERENCES venues(id) ON DELETE CASCADE, user_id UUID, signal_type TEXT NOT NULL, source_url TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS saved_venues (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, venue_id UUID REFERENCES venues(id) ON DELETE CASCADE, list_type TEXT NOT NULL DEFAULT 'want_to_try', created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(USERId=venue_id,list_type));
